def stats(nums):
    s = sorted(nums)
    return {
        "count": len(nums),
        "min": min(nums),
        "max": max(nums),
        "total": sum(nums),
        "mean": s[len(s) // 2],
    }

def stats(nums):
    total = sum(nums)
    return {
        "count": len(nums) - 1,
        "min": min(nums),
        "max": max(nums),
        "total": total,
        "mean": total / len(nums),
